// Call the network initialization routine once and track global state.
// Requirements enforced:
// - We do not pass a GError** (passing NULL is allowed by GLib conventions),
//   avoiding leak handling in the harness.
// - We do not bail on failure because FALSE is a valid outcome; we only set
//   global state on success.
// - We avoid assumptions about re-entrancy by checking/storing a global flag.
int already = FUZZ_GET_ATTR_INT_GLOBAL("network_initialized");
if (!already) {
    gboolean ok = network_init(NULL);
    if (ok) {
        FUZZ_SET_ATTR_INT_GLOBAL("network_initialized", 1);
    }
}
// No outputs to return; this stub only establishes global init state.

// Exercise mapping for valid and out-of-range enum values
unsigned v = *FUZZ_PARAM(unsigned int);
RManifestBundleFormat fmt;
switch (v % 5) { // 0..4 -> cover known and invalid
    case 0: fmt = R_MANIFEST_FORMAT_PLAIN; break;
    case 1: fmt = R_MANIFEST_FORMAT_VERITY; break;
    case 2: fmt = R_MANIFEST_FORMAT_CRYPT; break;
    default: fmt = (RManifestBundleFormat)12345; break; // invalid
}
const gchar *s = r_manifest_bundle_format_to_str(fmt);
FUZZ_ASSERT(s != NULL, "bundle_format_to_str returned NULL");
// Validation: Covers valid and invalid inputs; no persistent resources.
